    # Color the 8-valued cells in row bands. Observed demonstrations use
    # 2 for the topmost occupied row, 4 for the next, 1 for central rows,
    # and 3 for the bottommost occupied row.
    occupied = [r for r, row in enumerate(grid) if any(v == 8 for v in row)]
    out = [[0] * len(row) for row in grid]
    if not occupied:
        return out
    lo, hi = min(occupied), max(occupied)
    for r, row in enumerate(grid):
        if r < lo or r > hi:
            continue
        if r == lo:
            color = 2
        elif r == hi:
            color = 3
        elif r == lo + 1:
            color = 4
        else:
            color = 1
        for c, value in enumerate(row):
            if value == 8:
                out[r][c] = color
    return out
'''
