content='''def transform(grid):
    # Tile every 8-cell shape into 2x2 monochrome squares (1) and three-cell
    # L-tetromino? actually triomino corner pieces: colors encode missing corner.
    # Resolve exact cover against all supported tile types.
    h, w = len(grid), len(grid[0]) if grid else 0
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]
    # L triominoes: remove top-left=2, bottom-left=3, top-right=4, bottom-right=5.
    missing_color = [2, 4, 3, 5]
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
            if square <= occupied:
                tiles.append((square, 1))
            for miss in range(4):
                piece = square - {(r + miss//2, c + miss%2)}
                if piece <= occupied:
                    tiles.append((piece, missing_color[miss]))
    # exact-cover backtracking; prefer full squares, then legal L triominoes
    def solve(rem):
        if not rem:
            return []
        cell = min(rem, key=lambda p: sum(p in cells and cells <= rem for cells, _ in tiles))
        candidates = [(cells, color) for cells, color in tiles if cell in cells and cells <= rem]
        candidates.sort(key=lambda t: -len(t[0]))
        for cells, color in candidates:
            rest = solve(rem - cells)
            if rest is not None:
                return [(cells, color)] + rest
        return None
    solution = solve(occupied)
    if solution is None:
        return [[0 if v == 0 else 1 for v in row] for row in grid]
    for cells, color in solution:
        for r, c in cells:
            out[r][c] = color
    return out
'''
